    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">(JM) // (AE)</span>"},{"quoi":"الاختيار","math":"المطلوب : كتابة النّسب المتساوية. نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (JM) // (AE).</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث BAE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(JM) // (AE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">J ∈ (BA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M ∈ (BE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">BJ</span><span class=\"den\">BA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BM</span><span class=\"den\">BE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">JM</span><span class=\"den\">AE</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">BJ</span><span class=\"den\">BA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BM</span><span class=\"den\">BE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">JM</span><span class=\"den\">AE</span></span>"}],
    indice: "الرّؤوس تُقرأ انطلاقا من B : ثلاث نسب متساوية",
